const user = createResource({
  key: ['user', userId],
  source: {
    fetch: () => api.users.get(userId),
    save: (draft) => api.users.update(userId, draft),
  },
  validate: { on: 'blur', fields: {
    email: (v) => (!v?.includes('@') ? 'Invalid email' : null),
  }},
  persist: { draft: true, debounce: 300 },
});

