const neu = createResource({
  key: ['user', 'new'],
  initialData: { name: '', email: '', role: 'member' },
  source: {
    save: async (draft) => {
      const created = await api.users.create(draft);
      return created; // becomes new source
    },
  },
});

createResource({
  key: ['settings', orgId],
  mutation: { optimistic: true },
  onSaveError: (e) => toast.error(e.message),
  source: {
    fetch: () => api.settings.get(orgId),
    save: (d) => api.settings.put(orgId, d),
  },
});

